models.declaration:
export type AssessmentClientIdentity = {
  canonicalClientId: string | null;
  residentKey: string | null;
};

export type AssessmentCompletionRule = {
  key: string;
  label: string;
  fields: readonly AssessmentToolFieldKey[];
  mode: "all" | "any";
};

export type AssessmentFieldOwner =
  | "referral_context"
  | "assessment_answer"
  | "system_provenance";

export type AssessmentFieldWritingSpec = {
  field: AssessmentToolFieldKey;
  label: string;
  preferredFormat: AssessmentAnswerFormat;
  formatLabel: string;
  lengthGuidance: string;
  formatTemplate: string;
  instructionSteps: readonly AssessmentWritingInstruction[];
  requiredElements: readonly string[];
  strongExample: string;
  guardrail: string;
};

export type AssessmentWritingInstruction = {
  title: string;
  instruction: string;
};

export type ParsedAssessmentFile = {
  fields: AssessmentExtractionField[];
  matchConfidence: number;
  format: "csv" | "json" | "xlsx";
};

export type AssessmentQuestionRule = {
  field: AssessmentToolFieldKey;
  operator: "equals" | "includes" | "not_equals" | "one_of";
  value: string | readonly string[];
};

export type AssessmentInterviewQuestion = {
  field: AssessmentToolFieldKey;
  group: string;
  control: AssessmentQuestionControl;
  options?: readonly AssessmentQuestionOption[];
  showWhen?: AssessmentQuestionRule;
  requiredWhen?: AssessmentQuestionRule;
  help?: string;
  placeholder?: string;
  span?: "full" | "half";
  min?: number;
  max?: number;
};

export type AssessmentInterviewSectionDefinition = {
  key: AssessmentToolSection;
  label: string;
  description: string;
};

export type AssessmentLifecycleCommand = {
  if_match: number;
  client_mutation_id?: string;
};

export type AssessmentScheduleCommand = AssessmentLifecycleCommand & {
  schedule: AssessmentScheduleUpdate;
  allow_conflict?: boolean;
};

export type AssessmentAddendumCommand = AssessmentLifecycleCommand & {
  note: string;
  reason_code: string;
};

export type AssessmentCompletionBlocker = {
  code: string;
  label: string;
  fields?: AssessmentToolFieldKey[];
};

export type AssessmentNarrativeGuide = {
  field: AssessmentToolFieldKey;
  label: string;
  domain: AssessmentNarrativeGuideDomain;
  purposeTrack: AssessmentNarrativePurpose;
  purpose: string;
  reviewQuestion: string;
  thingsToCover: readonly string[];
  strongPattern: string;
  guardrail: string;
};

export type AssessmentActor = {
  id: string;
  name: string;
};

export type AssessmentScheduleUpdate = {
  start_at: string | null;
  duration_minutes: number | null;
  method: AssessmentScheduleMethod | null;
  location: string | null;
  status: AssessmentScheduleStatus;
};

export type AssessmentAddendum = {
  addendum_id: string;
  assessment_id: string;
  version: number;
  note: string;
  reason_code: string;
  authored_by: string;
  authored_by_name: string;
  created_at: string;
};

export type AssessmentAuditEvent = {
  event_id: string;
  assessment_id: string;
  referral_id: number;
  action: AssessmentAuditAction;
  actor_id: string;
  actor_name: string;
  changed_fields: AssessmentToolFieldKey[];
  created_at: string;
};

export type PipelineAssessmentRecord = AssessmentToolRecord & {
  referral_id: number;
  assessor_id: string | null;
  status: AssessmentWorkflowStatus;
  completed_at: string | null;
  created_by: AssessmentActor;
  updated_by: AssessmentActor;
  audit_events: AssessmentAuditEvent[];
  section_versions: AssessmentSectionVersions;
  scheduled_start_at?: string | null;
  scheduled_duration_minutes?: number | null;
  scheduled_method?: AssessmentScheduleMethod | null;
  scheduled_location?: string | null;
  schedule_status?: AssessmentScheduleStatus;
  started_at?: string | null;
  signed_at?: string | null;
  /** Successful Meet the Client delivery freezes ordinary edits; sourced additions retain the sent version. */
  meet_client_sent_at?: string | null;
  meet_client_sent_version?: number | null;
  signed_by?: AssessmentActor | null;
  signature_version?: number;
  addenda?: AssessmentAddendum[];
  revision_root_id?: string;
  revision_number?: number;
  supersedes_assessment_id?: string | null;
};

export type AssessmentListResponse = {
  assessments: PipelineAssessmentRecord[];
  total: number;
  revision: number;
  next_cursor: string | null;
  generated_at: string;
  store: {
    mode: "local_file" | "postgres";
    multi_instance_safe: boolean;
  };
};

export type AssessmentCreateInput = {
  referral_id: number;
  /** Server-resolved from the referral's authoritative assignment. */
  assigned_assessor?: AssessmentActor | null;
  canonical_client_id?: string | null;
  resident_key?: string | null;
  data: AssessmentToolData;
  status?: AssessmentWorkflowStatus;
  field_provenance?: Partial<Record<AssessmentToolFieldKey, AssessmentFieldProvenance[]>>;
  unmapped_fields?: UnmappedAssessmentField[];
};

export type AssessmentPatchInput = {
  data?: Partial<AssessmentToolData>;
  /** A sourced, field-specific addition after Meet the Client was sent. It never sends another email. */
  post_send_review?: { field: AssessmentToolFieldKey; source: string };
  workbook_restore?: AssessmentWorkbookRestoreSource;
  /** Server-resolved only. Browser requests supply an active workspace member ID. */
  assigned_assessor?: AssessmentActor | null;
  /** Server-resolved only. A canonical identity can be attached once and never changed. */
  canonical_client_id?: string | null;
  resident_key?: string | null;
  status?: AssessmentWorkflowStatus;
  accept_pending?: boolean;
  review_extraction?: Array<{
    field: AssessmentToolFieldKey;
    action: "accept" | "reject";
  }>;
  /** Answers the person chose from the client's last signed assessment; the route verifies them. */
  prior_answers?: Array<{ field: AssessmentToolFieldKey; assessment_id: string }>;
  /** Server-resolved only: verified sources for prior_answers. Browser payload validation rejects it. */
  prior_answer_sources?: Partial<Record<AssessmentToolFieldKey, { assessment_id: string; signed_at: string; referral_id: number }>>;
  /** Answers the person took from the referral intake ("Suggested from referral records"). */
  referral_answers?: AssessmentToolFieldKey[];
  /** Server-resolved only: intake provenance for referral_answers the server verified. Browser payload validation rejects it. */
  referral_answer_sources?: Partial<Record<AssessmentToolFieldKey, AssessmentFieldProvenance>>;
  /** Server-only lifecycle commands. Browser payload validation rejects these fields. */
  schedule?: AssessmentScheduleUpdate;
  mark_started?: boolean;
  signer?: AssessmentActor;
};

export type AssessmentCompletionReportRow = {
  assessor_id: string | null;
  assessor_name: string;
  /** Signed clinical encounters in the selected month. */
  completed_assessments: number;
  average_duration_minutes: number | null;
  /** Accepted supervisor decisions linked to those signed encounters, recorded to date. */
  accepted_clients: number;
};

export type AssessmentCompletionReport = {
  month: string;
  period_start: string;
  period_end: string;
  total_completed: number;
  rows: AssessmentCompletionReportRow[];
  generated_at: string;
};

export type AssessmentScheduleDraft = {
  start: string;
  duration: string;
  method: AssessmentScheduleMethod;
  location: string;
  base: string;
};

export type AssessmentPatchOptions = {
  expectedVersion?: number;
  expectedReferralName?: string;
  section?: AssessmentToolSection;
  expectedSectionVersion?: number;
  mutationId?: string;
  allowScheduleConflict?: boolean;
};

export type AssessmentScheduleConflict = {
  assessment_id: string;
  referral_id: number;
  starts_at: string;
  duration_minutes: number;
};

export type AssessmentListOptions = {
  referralId?: number;
  canonicalClientId?: string;
  residentNumber?: string;
  residentKey?: string;
  limit?: number;
  cursor?: string;
};

export type AssessmentStoreReadiness = {
  mode: "local_file" | "postgres";
  ready: boolean;
  multi_instance_safe: boolean;
  message?: string;
};

export type AssessmentMutation =
  | { ok: true; assessment: PipelineAssessmentRecord; revision: number; referral?: Referral; warnings?: ReturnType<typeof getAssessmentCompletionBlockers> }
  | { ok: false; conflict: true; assessment: PipelineAssessmentRecord; referralNameConflict?: boolean }
  | {
      ok: false;
      blocked: true;
      assessment: PipelineAssessmentRecord;
      blockers: { code: string; label: string; fields?: AssessmentToolFieldKey[] }[];
    };

export type AssessmentAddendumMutation =
  | { ok: true; assessment: PipelineAssessmentRecord; addendum: AssessmentAddendum; revision: number }
  | { ok: false; conflict: true; assessment: PipelineAssessmentRecord }
  | { ok: false; blocked: true; assessment: PipelineAssessmentRecord; blockers: { code: string; label: string }[] };

export type AssessmentImportInput = {
  referralId: number;
  /** Server-resolved from the referral's authoritative assignment. */
  assignedAssessor?: AssessmentActor | null;
  canonicalClientId?: string | null;
  residentKey?: string | null;
  assessmentId?: string;
  expectedVersion?: number;
  fields: AssessmentExtractionField[];
  context: AssessmentExtractionContext;
  defaults: Partial<AssessmentToolData>;
  actor: AssessmentActor;
  mutationId?: string;
};

export interface AssessmentStore {
  list(options?: AssessmentListOptions): Promise<AssessmentListResponse>;
  get(assessmentId: string): Promise<PipelineAssessmentRecord | null>;
  create(input: AssessmentCreateInput, actor: AssessmentActor, mutationId?: string): Promise<AssessmentMutation>;
  patch(assessmentId: string, patch: AssessmentPatchInput, actor: AssessmentActor, options?: AssessmentPatchOptions): Promise<AssessmentMutation | null>;
  importExtraction(input: AssessmentImportInput): Promise<AssessmentMutation | null>;
  addAddendum(
    assessmentId: string,
    note: string,
    reasonCode: string,
    actor: AssessmentActor,
    expectedVersion: number,
    mutationId?: string,
  ): Promise<AssessmentAddendumMutation | null>;
}

export type AssessmentSummaryItem = {
  label: string;
  value: string;
};

export type AssessmentSummarySection = {
  id: string;
  title: string;
  items: AssessmentSummaryItem[];
