  dateOfBirth: string;
  community: string;
  assessmentDate: string;
  admissionDate: string;
  bio: string[];
  medications: string[];
  medicationNotes: AssessmentSummaryItem[];
  supportSnapshot: AssessmentSummaryItem[];
  admissionNotes?: AssessmentSummaryItem[];
