  county?: string;
  source: string;
  priority: Priority;
  tags?: string[];
  documentName: string;
  documentSizeBytes?: number;
  /** SHA-256 of the original packet bytes for content integrity. */
  documentHash?: string;
  documentStatus: "Missing" | "Uploaded" | "Reviewed";
  /** Stable Entra object id for assignment enforcement. */
  ownerId?: string;
  owner: string;
  /** Current accountable owners. `owner`/`ownerId` remain the primary assessment assignment. */
  owners?: ReferralOwner[];
  assignedAt?: string;
  assignmentDueAt?: string;
  assignmentVersion?: number;
  note: string;
  createdAt: string;
  updatedAt?: string;
  dob: string;
  gender?: string;
