  reportedAge?: string;
  ssn?: string;
  /** Legacy admission date; imported records carry governed admission history here. */
  admissionDate?: string;
  /** Planned arrival date supplied with the outgoing packet, separate from actual arrival. */
  plannedAdmissionDate?: string;
  /** Actual arrival date, recorded only by an explicit admission confirmation. */
  actualAdmissionDate?: string;
  responsiblePerson?: string;
  /** Pre-assessment medication list or notes. This seeds assessment.medications_at_intake. */
  currentMedications?: string;
  /** @deprecated Legacy Allo-era narrative. New interview answers belong to assessment records. */
  interview?: string;
  conserved?: "yes" | "no" | "";
  fieldSources?: Partial<Record<ReferralCanvasFieldKey, string>>;
  phone: string;
  email: string;
  referrerName?: string;
  payer: string;
  packetId?: string;
  packetStatus?: PacketStatusResponse["status"];
  packetFields?: ExtractedField[];
  packetReadiness?: PacketFieldsResponse["ehr_readiness"];
  packetCompleteness?: PacketFieldsResponse["packet_completeness"];
  packetMessage?: string;
  /** Explicit, audited authorization to complete intake from the chart while source files remain outstanding. */
  manualIntakeAuthorization?: ManualIntakeAuthorization;
  /** @deprecated Legacy embedded assessment projection. Canonical assessments use the assessment store. */
  assessment?: AssessmentProfile;
  assessmentDocumentName?: string;
  assessmentDocumentSizeBytes?: number;
  assessmentMessage?: string;
  requirements?: AdmissionRequirement[];
  /** Completed ordinary document uploads for the durable local-store adapter. */
  additionalDocuments?: Array<{ id: string; name: string; uploadedAt: string }>;
  /** Synchronized decision projection. PostgreSQL stores the authoritative row separately. */
  admissionDecision?: AdmissionDecision;
  /** Prior decisions retained when a denial is explicitly reopened. */
  admissionDecisionHistory?: AdmissionDecision[];
  /** A later placement outcome; the accepted decision and sent handoff remain historical evidence. */
  placementCancellation?: PlacementCancellation;
  admissionFlow?: AdmissionFlowTracking;
  /** Latest assessor recommendation. The supervisor's decision remains authoritative. */
  assessmentRecommendation?: AssessmentRecommendation;
  /** Latest durable supervisor review projection. PostgreSQL stores the authoritative row separately. */
  assessmentReview?: AssessmentReview;
  /** Local-store history for immutable review submissions and outcomes. */
  assessmentReviewHistory?: AssessmentReview[];
  /** Pipeline-owned handoff state. This never represents an EHR write unless status is sent. */
  ehrHandoff?: EhrHandoffRecord;
};

